 b=pw.chromium.launch(executable_path=os.environ.get('INK_CHROMIUM') or shutil.which('chromium'),headless=True,args=['--no-sandbox']);p=b.new_page();p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(data.decode(),wait_until='load',timeout=60000);p.wait_for_function('window.INKRhythmLab?.ready');rows=p.evaluate('''()=>{const A=SVG_FIGHTER,C=INK.Combo,V=INK.VFX,T=INK.CombatFlow,rows=[];T.set({rhythm:'weighted',rules:'flow',speed:1});for(const r of C.routes.routes.filter(x=>x.rulesPreset==='flow'))for(const side of [1,-1]){let reference=null;for(const mode of ['full','reduced','off']){V.setEnabled(mode!=='off');V.settings.reducedMotion=mode==='reduced';V.settings.intensity=mode==='reduced'?.65:1;C.start(r,'demo',{paused:true,side});for(let i=0;i<1600&&C.status==='running';i++){A.step();A.renderFraction((i%3)/2);}const q=C.summary(),outcome={status:q.status,hits:q.hits,damage:q.damage,ticks:q.elapsedTicks,actionFrames:q.actionFrames,remaining:q.remaining};if(!reference)reference=JSON.stringify(outcome);rows.push({route:r.id,side,mode,...outcome,pass:q.status==='success'&&JSON.stringify(outcome)===reference});C.stop();}}V.setEnabled(true);V.settings.reducedMotion=false;V.settings.intensity=1;return rows;}''');b.close()
